<script setup lang="ts">
import GlassSlider from './glass/GlassSlider.vue'
import GlassDropdown from './glass/GlassDropdown.vue'
import GlassDropdownMenu from './glass/GlassDropdownMenu.vue'
import GlassDropdownItem from './glass/GlassDropdownItem.vue'
import { ref, watch, onMounted, onBeforeUnmount } from 'vue'
import { ChatDotRound, DArrowLeft, DArrowRight, Headset, InfoFilled, Menu, MoreFilled, Mute, Refresh, Share, Sort, Star, VideoPause, VideoPlay, Download } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { usePlayerStore } from '../store/player'; import { useAuthStore } from '../store/auth'; import { api } from '../api'
import QueuePanel from './QueuePanel.vue'; import CommentPanel from './CommentPanel.vue'; import ShareDialog from './ShareDialog.vue'; import TrackInfoPanel from './TrackInfoPanel.vue'; import NowPlayingPanel from './NowPlayingPanel.vue'
const player=usePlayerStore(), auth=useAuthStore(), audio=ref<HTMLAudioElement>(), queueOpen=ref(false), commentsOpen=ref(false), shareOpen=ref(false), infoOpen=ref(false), nowPlayingOpen=ref(false)
watch(()=>player.track,()=>{if(!audio.value)return;audio.value.load();syncAudio();if(player.playing)audio.value.play().catch(()=>player.setError('音频播放失败，请检查作品地址'))},{flush:'post'})
watch(()=>player.playing,v=>{if(!audio.value)return;if(v)audio.value.play().catch(()=>player.setError('音频播放失败'));else audio.value.pause()}); watch(()=>[player.volume,player.muted],syncAudio)
watch(()=>player.seekRevision,()=>{if(audio.value&&Math.abs(audio.value.currentTime-player.current)>0.25)audio.value.currentTime=player.current})
function syncAudio(){if(audio.value){audio.value.volume=player.volume;audio.value.muted=player.muted}} function onTime(){if(audio.value){player.current=audio.value.currentTime;player.duration=audio.value.duration||player.duration}}
function seek(value:number|string){if(audio.value)audio.value.currentTime=Number(value);player.current=Number(value)} function fmt(v:number){return `${Math.floor(v/60)}:${Math.floor(v%60).toString().padStart(2,'0')}`} function onEnded(){player.next(true)} function onError(){player.setError('音频加载失败，请稍后重试')}
async function favorite(){if(!player.track)return;if(!auth.user){ElMessage.info('登录后可以收藏作品');return}const next=!player.isFavorite(player.track);try{const updated=await api.favoriteTrack(player.track.id,next);player.syncFavorite(player.track.id,!!updated.favorite);ElMessage.success(next?'已收藏':'已取消收藏')}catch{}}
function download(){if(player.track)window.open(`/api/v1/music-library/${player.track.id}/download`,'_blank')} function moreAction(action:string){if(action==='download')download();if(action==='share')shareOpen.value=true;if(action==='info')infoOpen.value=true;if(action==='remove'&&player.track)player.removeFromQueue(player.track.id);if(action==='clear')player.clearQueue()}
function keys(event:KeyboardEvent){if(event.code==='Space'&&player.track&&!['INPUT','TEXTAREA'].includes((event.target as HTMLElement).tagName)){event.preventDefault();player.toggle()}} function openNowPlaying(){if(player.track)nowPlayingOpen.value=true} function openNowPlayingKey(event:KeyboardEvent){if((event.key==='Enter'||event.key===' ')&&player.track){event.preventDefault();openNowPlaying()}} onMounted(()=>window.addEventListener('keydown',keys));onBeforeUnmount(()=>window.removeEventListener('keydown',keys))
</script>
<template><div class="player qq-player player-redesign" data-lg-scene="player" :class="{'is-empty':!player.track}"><audio v-if="player.track" ref="audio" :src="player.track.audioUrl" @timeupdate="onTime" @loadedmetadata="onTime" @ended="onEnded" @error="onError"/><div class="player-track" :class="{'player-track-clickable':player.track}" :role="player.track?'button':undefined" :tabindex="player.track?0:-1" :aria-label="player.track ? `打开正在播放：${player.track.title}` : undefined" @click="openNowPlaying" @keydown="openNowPlayingKey"><div class="mini-cover"><img v-if="player.track?.coverUrl" :src="player.track.coverUrl" alt=""/><el-icon v-else><Headset/></el-icon></div><div class="player-track-copy"><strong>{{player.track?.title||'未选择歌曲'}}</strong><small>{{player.error||player.track?.styleTags||'从作品列表选择一首开始播放'}}</small></div></div><div class="qq-center"><div class="qq-controls"><button class="player-button" :class="{active:player.shuffle}" aria-label="随机播放" @click="player.toggleShuffle"><Sort/></button><button class="player-button" :disabled="!player.track" aria-label="上一首" @click="player.previous"><DArrowLeft/></button><button class="play player-button" :disabled="!player.track" aria-label="播放或暂停" @click="player.toggle"><VideoPause v-if="player.playing"/><VideoPlay v-else/></button><button class="player-button" :disabled="!player.track" aria-label="下一首" @click="()=>player.next()"><DArrowRight/></button><button class="player-button" :class="{active:player.repeat!=='off'}" :aria-label="player.repeat==='one'?'单曲循环':player.repeat==='all'?'全部循环':'关闭循环'" @click="player.toggleRepeat"><Refresh/><i v-if="player.repeat==='one'">1</i></button></div><div class="timeline"><span>{{fmt(player.current)}}</span><GlassSlider :disabled="!player.track" :model-value="player.current" :max="player.duration||1" :step="1" aria-label="播放进度" :show-tooltip="false" @input="seek"/><span>{{fmt(player.duration)}}</span></div></div><div class="qq-actions player-action-group"><button class="player-button" aria-label="打开播放队列" @click="queueOpen=!queueOpen"><Menu/></button><button class="player-button" :class="{active:player.track&&player.isFavorite(player.track)}" :disabled="!player.track" aria-label="收藏当前作品" @click="favorite"><Star/></button><button class="player-button" :disabled="!player.track" aria-label="打开评论" @click="commentsOpen=true"><ChatDotRound/></button><button class="player-button" :disabled="!player.track" aria-label="分享当前作品" @click="shareOpen=true"><Share/></button><GlassDropdown @command="moreAction"><button class="player-button" :disabled="!player.track" aria-label="更多操作"><MoreFilled/></button><template #dropdown><GlassDropdownMenu><GlassDropdownItem command="download"><Download/>下载音频</GlassDropdownItem><GlassDropdownItem command="info"><InfoFilled/>作品详情</GlassDropdownItem><GlassDropdownItem command="share"><Share/>分享作品</GlassDropdownItem><GlassDropdownItem command="remove">从队列移除</GlassDropdownItem><GlassDropdownItem command="clear">清空播放队列</GlassDropdownItem></GlassDropdownMenu></template></GlassDropdown><button class="player-button" aria-label="静音或恢复音量" @click="player.toggleMute"><Mute/></button><GlassSlider class="volume-slider" aria-label="音量" :model-value="player.muted?0:player.volume" :min="0" :max="1" :step=".01" :show-tooltip="false" @input="(v:number)=>player.setVolume(Number(v))"/><button class="player-button" :disabled="!player.track" aria-label="查看作品信息" @click="infoOpen=true"><InfoFilled/></button></div><QueuePanel :open="queueOpen" @close="queueOpen=false"/><CommentPanel :open="commentsOpen" :track="player.track" @close="commentsOpen=false"/><ShareDialog :open="shareOpen" :track="player.track" @close="shareOpen=false"/><TrackInfoPanel :open="infoOpen" :track="player.track" @close="infoOpen=false"/><NowPlayingPanel :open="nowPlayingOpen" @close="nowPlayingOpen=false"/></div></template>
